from fetcher import fetch

def test_timeout_parameter():
    """Test that fetch passes timeout=30 to client.get"""
    # Mock client to verify timeout argument
    class MockClient:
        def get(self, url, timeout=None):
            assert timeout == 30, f"Expected timeout=30, got {timeout}"
            return "mock_response"

    client = MockClient()
    result = fetch(client, "http://example.com")
    assert result == "mock_response"

def test_exception_propagation():
    """Test that exceptions are propagated correctly"""
    class MockClient:
        def get(self, url, timeout=None):
            raise ConnectionError("Test error")

    client = MockClient()
    try:
        fetch(client, "http://example.com")
        assert False, "Expected ConnectionError"
    except ConnectionError as e:
        assert str(e) == "Test error"

if __name__ == "__main__":
    test_timeout_parameter()
    test_exception_propagation()
    print("All tests passed")
